head.script:
scwin.CHART_DATA_URL ="/ui/sample/SBChart/FEATURE/data/DONUT_TYPE.json";
scwin.CHART_CONFIG = {
    global: { color: { theme: "pastel" } },
    extend: {
        donut: {
            multiDatas: [                                  // ★ 동심 도넛(여러 링) — 각 배열이 하나의 링
                [ { id:"a1", name:"영업", value:70, color:"#4e79a7" }, { id:"a2", name:"잔여", value:30, color:"#e5e5e5", visible:false } ],
                [ { id:"b1", name:"개발", value:55, color:"#59a14f" }, { id:"b2", name:"잔여", value:45, color:"#e5e5e5", visible:false } ],
                [ { id:"c1", name:"지원", value:40, color:"#f28e2b" }, { id:"c2", name:"잔여", value:60, color:"#e5e5e5", visible:false } ]
            ]
        }
    }
};
scwin.onpageload = async function () {
    const res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.CHART_DATA_URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    const data = res.responseJSON;
    $c.ext.drawSBChart(chartWrap, data, scwin.CHART_CONFIG);
};
